            hx = hex_of(val)
            key = (ipath, representation, hx or str(val)[:20])
            if key in seen_hit:
                continue
            seen_hit.add(key)
            if representation == "capability-manifest-id" or retention == "derived":
                digest_hits.append({"path": ipath, "kind": "derived", "value": val})
