            raw = blobs[hx]
            if sha256_hex(raw) != hx:
                digest_fail.append({"path": ipath, "reason": "rehash"})
                continue
            if representation == "canonical-record":
                if raw[:1] in (b"{", b"["):
                    parsed = json.loads(raw)
                    if C_encode(parsed) != raw:
                        digest_fail.append({"path": ipath, "reason": "canonical-remainder"})
                        continue
            elif representation == "h-identity":
                fr = parse_h_frame(raw)
                if not fr or "obj" not in fr:
                    digest_fail.append({"path": ipath, "reason": "h-frame"})
